/**
 * county-survey data: North Carolina's 100 counties and their neighbours, interstates and US highways,
 * lakes and rivers, a 1 km elevation grid for the mountain counties, sound names, and the state outline.
 * Imported only by v1.ts. Frozen with v1 (ADR 0021): a change here redraws locked sites, so new data
 * means a new data file for a new version.
 *
 * Projection: NC State Plane (Lambert conformal conic, NAD83; standard parallels 34°20'N and 36°10'N,
 * central meridian 79°W, origin 33°45'N). Geometry is pre-projected, simplified (Visvalingam-Whyatt for
 * boundaries, Douglas-Peucker for lines), quantized to 20 m (`U`, metres per unit, from origin `O`),
 * and delta-encoded as zigzag base-45 varints over a 90-character alphabet (`decLine` in plotter/v1.ts).
 * Boundaries are shared arcs (`A`, space-separated; a ring lists arc indices, ~i for one reversed).
 * The elevation grid (`DEM`) is one character per cell (a space and a count for a run of no data); a
 * "!" after every eleventh figure in a row of figures is skipped (it keeps the repo's ID check quiet).
 *
 * Sources: county boundaries, U.S. Census Bureau cartographic boundary file 2024 (1:500k, public domain);
 * interstates and US highways, U.S. Census TIGER/Line 2024 primary and secondary roads (public domain);
 * lakes and rivers © OpenStreetMap contributors (ODbL 1.0, https://www.openstreetmap.org/copyright);
 * elevation, USGS 3DEP (public domain); seat locations, Census 2024 Gazetteer and USGS GNIS (public
 * domain); sound names and positions, USGS GNIS; county seats and formation years cross-checked between
 * Wikipedia's "List of counties in North Carolina" and NCpedia (the formation year is the act creating
 * the county or its precinct, per NCpedia; Beaufort and Hyde 1705, Wilkes 1777).
 */

/** One county: name, state, parts (rings of arc indices), FIPS code, and (outside NC) its full name. */
export type CountyRecord = [string, string, number[][][], string] | [string, string, number[][][], string, string];

/** An NC county's sheet: seat, formation year, seat position, neighbours, roads, rivers, lakes, and kind. */
export interface CountyInfo {
  s: string;
  f?: number;
  sx: number;
  sy: number;
  nb: number[];
  rd: number[];
  rv: number[];
  lk: number[];
  /** A mountain county: contours. */
  m?: number;
  /** A coastal county: the stippled water edge. */
  c?: number;
  /** Where to letter ATLANTIC OCEAN. */
  oc?: number[];
}

export interface CountyData {
  U: number;
  O: number[];
  A: string;
  C: CountyRecord[];
  I: Record<string, CountyInfo>;
  R: string;
  RM: string[];
  V: string;
  VN: number[];
  VNames: string[];
  L: string;
  LN: string[];
  NC: string;
  NCI: string[];
  WL: [string, number, number][];
  DEM: { x0: number; y1: number; cs: number; nx: number; ny: number; lo: number; st: number; d: string };
}

